style.css:
@-moz-document domain("roblox.com") {
/* Replace grey backgrounds with green */
    body, .container, .content, #app, #rbx-body, .navbar, .footer, .card, .section, .sidebar {
        background-color: #467844 !important;
    }

    /* Replace dark grey with black */
    .dark-background, .header, .footer, .sidebar, .modal, .dropdown-menu, .menu-bar {
        background-color: #000000 !important;
    }

    /* Set all text to white for readability */
    p, h1, h2, h3, h4, h5, h6, span, a, .text, .label, .btn, .navbar a, .footer a {
        color: #ffffff !important; /* White text */
    }

    /* Style buttons with green background and white text */
    .btn-primary, .btn-secondary, .btn {
        background-color: #3d8c5e !important; /* Darker green for buttons */
        color: #ffffff !important; /* White text on buttons */
    }

    /* Border adjustments */
    .border, .card, .section, .sidebar, .navbar, .footer, .header {
        border-color: #467844 !important; /* Green borders */
    }
}
